using System.Linq;
using Autodesk.Revit.DB;
using Autodesk.Revit.DB.Electrical;

var doc = Document;
// setup: a conduit type and the lowest level (Conduit.Create takes the TYPE first, then points, then level)
var conduitType = new FilteredElementCollector(doc).OfClass(typeof(ConduitType)).Cast<ConduitType>().First();
var level = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l => l.Elevation).First();
var start = new XYZ(0, 10, 9);
var end   = new XYZ(20, 10, 9);

ElementId id = null;
Connector.WithTransaction(doc, () => {
    var c = Conduit.Create(doc, conduitType.Id, start, end, level.Id);
    id = c.Id;
});

var created = (Conduit)doc.GetElement(id);
var length = created.get_Parameter(BuiltInParameter.CURVE_ELEM_LENGTH)?.AsDouble();
return new { id = id.ToString(), conduitType = conduitType.Name, level = level.Name, lengthFeet = length };
